query loadSearchData($enableContentful: Boolean!) {
    globalComponents

    games(published: true) @skip(if: $enableContentful) {
      id
      title
      link
      imageSlug
      categoryId
      subCategoryId
      order
      tags {
        value
      }

fragment GameFragment on GameType {
    id
    title
    imageSlug
    added
    authorName
    author {
      id
      name
      image
    }
    order
    backgroundColour
    visible
    indexed
    categoryId
    subCategoryId
    introduction
    heroCaption
    canonical
    howToPlay
    metaTitle
    customRegistrationUrl
    customZeroBannerBackgroundColor
    customUKGCLink
    customUKGCText
    socialLink
    socialType
    metaDescription
    tags {
      value
      link
    }
    provider {
      name
      legalInfo
      bynderImage {
        transformBaseUrl
        name
      }
    }
    gameFeatures {
      enabled
      value
      type
    }
    video
    providerId
    content {
      type
      props {
        text
        imageUrl
        imageAlt
        imageCaption
        videoUrl
        videoAlt
        videoThumbnail
        tableData
      }
    }
    jackpot {
      id
      amount
    }
    jsonld
    pageFooterOverride
    overrideComponents
    jsonldHowTo {
      name
      image
      totalTime
      hasJsonldHowTo
      step {
        name
        text
        image
      }
      tool {
        name
      }
      supply {
        name
      }
    }
    crossSellQuery
    imageVariants
    offer
}
query loadPageOrGame(
  $path: String,
  $released: Boolean,
  $variant: Int,
  $enableContentful: Boolean!,
  $resourceId: String,
  $categoryId: String,
  $isPage: Boolean!,
  $isGame: Boolean!,
  $isBlog: Boolean!
) {
  pageOrGame(path: $path, released: $released, variant: $variant) @skip(if: $enableContentful){
    page {
      title
      customTermsAndConditions
      path
      metaTags
      canonical
      components {
        type
        props
      }
      published
      jsonld
      indexed
      pageFooterOverride
      overrideComponents
      jsonldFAQ {
        hasJsonldFAQ
        arrayOfJsonldFAQ {
          question
          answer
        }
      }
      disableBreadcrumb
    }
    game {
      id
      title
      imageSlug
      added
      authorName
      author {
        id
        name
        image
      }
      order
      backgroundColour
      visible
      indexed
      categoryId
      subCategoryId
      introduction
      heroCaption
      canonical
      howToPlay
      metaTitle
      customRegistrationUrl
      customZeroBannerBackgroundColor
      customUKGCLink
      socialLink
      socialType
      metaDescription
      tags {
        value
        link
      }
      gameFeatures {
        enabled
        value
        type
      }
      video
      providerId
      content {
        type
        props {
          text
          imageUrl
          imageAlt
          imageCaption
          videoUrl
          videoAlt
          videoThumbnail
          tableData
        }
      }
      jackpot {
        id
        amount
      }
      jsonld
      pageFooterOverride
      overrideComponents
      jsonldHowTo {
        name
        image
        totalTime
        hasJsonldHowTo
        step {
          name
          text
          image
        }
        tool {
          name
        }
        supply {
          name
        }
      }
    }
  }
  globalContent @skip(if: $enableContentful){
    templates {
      name
      components {
        type
        props
      }
    }
    welcomeBonusTermsAndConditionsShort
    footerContent
    categories {
      slug
      name
      offer
      customUKGC
      customUKGCLink
      customRegistrationUrl
    }
    menuItems {
      link
      text
      enabled
      isDropdown
      isExternal
    }
    headerLang {
      hrefLang
      link
      pagePath
    }
    dropdownMenu
    appLinks {
      android
      ios
    }
    socialIcons {
      title
      href
      src
    }
    showBreadcrumb
    cookie {
      text
      buttonText
      enabled
    }
  }
  globalComponents @skip(if: $enableContentful)
  contentfulGlobalSettings @include(if: $enableContentful) {
    showBreadcrumb
    gameCrossSellQuery
    metaTags
    welcomeBonusTermsAndConditionsShort
    socialIcons
    searchIcon
  }
  contentfulBlog(blogId: $resourceId) @include(if: $isBlog) {
    id
    title
    imageSlug
    imageVariants
    added
    author {
      id
      name
      image
    }
    order
    backgroundColour
    visible
    indexed
    categoryName
    categoryId
    subCategoryName
    subCategoryId
    introduction
    heroCaption
    canonical
    howToPlay
    metaTitle
    customRegistrationUrl
    customZeroBannerBackgroundColor
    customUKGCLink
    socialLink
    socialType
    metaDescription
    tags {
      value
      link
    }
    gameFeatures
    video
    providerId
    content
    jackpot
    jsonld
    welcomeBonusTermsAndConditionsLong
  }
  contentfulHeader @include(if: $enableContentful)
  contentfulGame(gameId: $resourceId) @include(if: $isGame)  {
    ...GameFragment
  }
  contentfulPageOrGame(path: $path, gameId: $resourceId, categoryId: $categoryId) @include(if: $isPage) @skip(if: $isGame) {
    page {
      title
      path
      metaTags
      title
      canonical
      disableBreadcrumb
      jsonld
      overrideComponents
      pageFooterOverride
      customTermsAndConditions,
      components {
        type
        props
      }
      jsonldFAQ {
        hasJsonldFAQ
        arrayOfJsonldFAQ {
          question
          answer
        }
      }
    }
    game {
      ...GameFragment
    }
  }
}

query loadFooterContent($providers: [String], $enableContentful: Boolean!) {
  contentfulFooter @include(if: $enableContentful) {
    welcomeBonusTermsAndConditionsLong
    welcomeBonusTnCHeading
    primaryIcons {
      href
      title
      src
    }
    secondaryIcons {
      href
      title
      src
    }
    footerLinks {
      href
      text
    }
    footerContent
  }
  globalContent @skip(if: $enableContentful)  {
    welcomeBonusTermsAndConditionsShort
    globalFooter
    lang
  }
  providers (providers: $providers) @skip(if: $enableContentful) {
    image
    legalLine
    title
  }
}

query loadPageOrGame($path: String, $enableContentful: Boolean!) {
  pageOrGame(path: $path) @skip (if: $enableContentful) {
    page {
      components {
        type
        props
      }
    }
  }
  contentfulHeader @include(if: $enableContentful)
  contentfulGlobalSettings @include(if: $enableContentful) {
    showBreadcrumb
    gameCrossSellQuery
    metaTags
    welcomeBonusTermsAndConditionsShort
    socialIcons
  }
  contentfulPage(path: $path) @include(if: $enableContentful) {
    title
    path
    metaTags
    title
    canonical
    disableBreadcrumb
    jsonld
    overrideComponents
    pageFooterOverride
    customTermsAndConditions,
    components {
      type
      props
    }
    jsonldFAQ {
      hasJsonldFAQ
      arrayOfJsonldFAQ {
        question
        answer
      }
    }
  }
}

